INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Days to Die', 'Set in a brutally unforgiving post-apocalyptic world overrun by the undead, 7 Days to Die is an open-world game that is a unique combination of first person shooter, survival horror, tower defense, and role-playing games. It presents combat, crafting, looting, mining, exploration, and character growth, in a way that has seen a rapturous response from fans worldwide. Play the definitive zombie survival sandbox RPG that came first. Navezgane awaits!' FROM games WHERE igdb_id = 5574 ON CONFLICT (game_id, language_code) DO NOTHING;
