INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Once Upon an Island', 'You are a famous video blogger, a hunter of mystical stories, and your new project should blow up the internet. Following a fan''s tip, you go to the island of Adago, lost in the ocean, where people are rumored to be missing, and the locals are talking about an ancient curse. Your goal is to make a revealing video, to prove that all this is fiction... but from the very first minutes, something goes wrong.' FROM games WHERE igdb_id = 344857 ON CONFLICT (game_id, language_code) DO NOTHING;
