INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runic Relay: The Trials', 'Runic Relay: The Trials is a First Person Platforming game with a focus on Speedrunning. Play as an apprentice wizard who has entered in a competition called “The Trials.” Each trial takes place in a magically constructed dungeon, and consists of a short challenge that you must complete using the tools given to you. These tools include multiple spells, which you can use in tandem with one another to complete tasks that one spell alone might not be able to.' FROM games WHERE igdb_id = 159121 ON CONFLICT (game_id, language_code) DO NOTHING;
