INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Training Elves', 'You are an adventurer of some renown that has grown tired of adventuring. After losing almost all of your money gambling, you meet two elves that seek you out and put you to task of training them into adventurers. In exchange, they give you amorous nights.' FROM games WHERE igdb_id = 288901 ON CONFLICT (game_id, language_code) DO NOTHING;
