INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat''s Vote', 'Cat''s Vote is a resource management and decision-making simulation where every choice counts. As the head of a feline household, you must ensure your family''s happiness by meeting their needs—whether it''s electricity/water bills, food, or entertainment. But there''s a twist: the price of resources fluctuates based on the decisions of a cat government, and you get to cast your vote in the elections!
