INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minami Lane', 'Minami Lane is a small-scale management game where players build and manage a Japanese-inspired street. The game involves placing and customizing buildings, managing shops by adjusting inventory, recipes, and prices, and ensuring the happiness of the villagers. Each level has specific objectives that guide progression, while a sandbox mode allows for freeform play without goals. Additional mechanics include keeping the street clean by picking up trash and interacting with various animal inhabitants, such as tanukis and cats.' FROM games WHERE igdb_id = 276203 ON CONFLICT (game_id, language_code) DO NOTHING;
