INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capslock', 'Capslock is a casual game focused on design and testing your imagination. Choose between 100 skins, 195+ custom keys, 220+ symbols and more (so far) to test your designs and make unique keyboards. Relax as you listen to the ''clicky'' sounds, chosen to help you unwind and immerse into a keyboard building environment.
