INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CoinForge', 'CoinForge is a clicker game where you generate S-coins! Click to earn S-coins and exchange them. Try to get your S-Coins every day with every 100 Clicks you press. 3 is max per day. It''s time to forge fortune with Coin Forge. Join our community on Discord and help shape the game!' FROM games WHERE igdb_id = 338874 ON CONFLICT (game_id, language_code) DO NOTHING;
