INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Waiting Room: An Existential Simulation', 'Ever been to a waiting room? Ever wanted to? Well now''s your chance! Enter The Waiting Room, get your ticket number and wait. "For what?" you might ask. Does it matter? It is an existential life-simulation metaphor? Or a ridiculous waste of time? Well, that, my friends, is up to you.' FROM games WHERE igdb_id = 368319 ON CONFLICT (game_id, language_code) DO NOTHING;
