INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnage Kart X', 'Carnage Kart X is a retro-inspired hack n'' slash experience combining the feel of classic karting games from the early 90s with Vampire Survivors-like gameplay, combining hand-drawn 2D pixel art and low-poly 3D models for a new perspective on the Survivors-like genre. It''s style is reminiscent of something you''d play at the arcade down to the rockin'' over-the-top music and over-sized blood spurts/body parts flying off of enemies.' FROM games WHERE igdb_id = 318977 ON CONFLICT (game_id, language_code) DO NOTHING;
