INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Story Goes On Chapter 6', 'The heroes narrowly escape the collapsing Temple of Lumina, but their victory is short-lived as the corrupted crystal destabilizes, opening a rift to the Shadow Realm. Entering the Shadow Lord’s domain, they confront his growing power, ultimately shattering the crystal—only to inadvertently unleash him. Guided by a mysterious Keeper, the party embarks on a perilous journey to recover the Shards of Eternity, fragments of creation needed to restore balance across collapsing realms.' FROM games WHERE igdb_id = 337694 ON CONFLICT (game_id, language_code) DO NOTHING;
