INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mushroom Colors', 'Mushroom Colors is an exciting endless jumping game where you play as a vibrant mushroom. Your goal is to ascend as high as possible, navigating through colorful obstacles. Each obstacle matches a specific color, and your mushroom can only pass through if it matches the obstacle''s hue. Collect items to change your mushroom''s color and continue your ascent. Test your reflexes and see how far you can go in this challenging and colorful adventure!' FROM games WHERE igdb_id = 315380 ON CONFLICT (game_id, language_code) DO NOTHING;
