INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kozyrev Horrors', 'Step into the Kozyrev Mirror to unlock your Extra Sensory Perception. Beware: dread and horror await. Investigate to find an escape from this liminal space. Are you truly alone? A short and chilling singleplayer horror game, inspired by the Kozyrev Mirror experiments.' FROM games WHERE igdb_id = 287477 ON CONFLICT (game_id, language_code) DO NOTHING;
