INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Despair: Blood Curse', 'A third-person survival horror game featuring non-linear gameplay, puzzles, and enemies from the depths of hell. After the arrival of an unexpected guest back home, Anna''s in a race against time to uncover the mystery of the events that took place. Will she save her sister before it''s too late?' FROM games WHERE igdb_id = 153951 ON CONFLICT (game_id, language_code) DO NOTHING;
