INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am Going for a Beer', 'You''re just an ordinary guy, coming home after a long day. Beer in hand, TV on... but suddenly it runs out. Time to leave your cozy apartment, go down the stairs, cross the street, and get to the supermarket to find the best beer in the world. But isn’t this a strange dream? When will it end?' FROM games WHERE igdb_id = 360843 ON CONFLICT (game_id, language_code) DO NOTHING;
