INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beyond-good-and-evil-20th-anniversary-edition', 278326, '2024-06-25', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8eda.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar309g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond Good & Evil: 20th Anniversary Edition', 'Swoop into the marvelous world of Hillys as action-reporter Jade to investigate the mysterious DomZ alien attacks alongside colorful characters, like her adoptive uncle Pey’j or the valiant Double H. Embark on this epic adventure in up to 4K, 60 fps with improved graphics, controls, and audio, along with brand-new autosave and cross-save features. Enjoy exclusive new rewards as you explore the planet and discover more about Jade’s past in a new treasure hunt throughout Hillys. Put your skills to the test thanks to the new speedrun mode and updated achievements, and learn more about the game’s development and secrets in the anniversary gallery! Armed with her daï-jo and faithful camera, Jade’s adventure will get you to freely explore Hillys, combat creatures large and small, infiltrate dangerous areas, solve enigmatic puzzles, play addictive mini-games, race the best hovercraft pilots, and take pictures of the whole experience.' FROM games WHERE igdb_id = 278326 ON CONFLICT (game_id, language_code) DO NOTHING;
