INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('biblios-tome-of-darkness', 306343, '2024-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8qzo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar302n.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biblios: Tome of Darkness', 'Biblios: Tome of Darkness is a fast paced first person shooter inspired by the biggest hits of the 1990s and Boomer Shooter revival. Fight a host of unique and challenging enemies, wield a powerful arsenal of weapons, and search high and low for secrets and lore notes to reveal the mysterious motives of the evil Acolytes of Seth.' FROM games WHERE igdb_id = 306343 ON CONFLICT (game_id, language_code) DO NOTHING;
