INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duck Life 9: The Flock', 'Raise your ducklings into the ultimate team of racers in Duck Life 9, where everything is bigger, bolder & more beautiful than ever before! Embark on a quest as you journey across the huge Featherhaven Island, meeting new friends & taking on recruits to help topple the competition & take the crown!' FROM games WHERE igdb_id = 253309 ON CONFLICT (game_id, language_code) DO NOTHING;
