INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet Cute: Threads of Courage', 'In a world of anthropomorphic animals, Carlie, a sheep in his mid-30s, struggles with feeling out of place among his flock. His life takes an unexpected turn after a dangerous encounter with a wolf, where he is rescued by Leo, a lion who has rejected his predatory nature to embrace a vegetarian lifestyle. Despite their differences, Carlie and Leo form a close bond that helps them both rediscover their place in the world.' FROM games WHERE igdb_id = 337685 ON CONFLICT (game_id, language_code) DO NOTHING;
