INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat in Rain', 'Dive into the whimsical and challenging world of Cat in Rain, a captivating 2D precision platformer that combines classic gameplay with pixel-art graphics. Prepare for an adventure where every step matters, and every jump counts! Whether you''re a seasoned platformer veteran or a curious newcomer, Cat in Rain has something for everyone. Choose between Easy and Hardcore modes to tailor the challenge to your skill level.' FROM games WHERE igdb_id = 320764 ON CONFLICT (game_id, language_code) DO NOTHING;
