INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout 76: Gleaming Depths - Deluxe Edition', 'Bethesda Game Studios, the award-winning creators of Skyrim and Fallout 4, welcome you to Fallout 76. Twenty-five years after the bombs fell, you and your fellow Vault Dwellers—chosen from the nation''s best and brightest - emerge into post-nuclear America on Reclamation Day, 2102. Explore a vast wasteland, devastated by nuclear war, in this open-world multiplayer addition to the Fallout story.' FROM games WHERE igdb_id = 331817 ON CONFLICT (game_id, language_code) DO NOTHING;
