INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life Dream', 'If you’re the type who’s always watching DIY and home reno videos on social media, come immerse yourself in the vibrant world of Life Dream where you can unleash your creativity and design prowess to transform houses, blocks, and even cities. Enjoy captivating gameplay and a relaxing atmosphere as you clean, design, and upgrade to your heart’s content. Download now and embark on a journey of design and delight!' FROM games WHERE igdb_id = 331456 ON CONFLICT (game_id, language_code) DO NOTHING;
