INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fears to Fathom: Woodbury Getaway', 'In the fifth episode of Fears to Fathom you play as Sydney Harper, a 23-year-old working at a consulting firm plans a weekend getaway to a rental in Woodbury with her college friends. Little did they know what was about to unfold during their stay. Sydney survived as she made the right choices.' FROM games WHERE igdb_id = 281785 ON CONFLICT (game_id, language_code) DO NOTHING;
