INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend of Mortal', 'The game world is set in a turbulent state and the mighty Tang-Man declines. The threats from the old enemies keep coming one after another.As a nobody, will you choose either to leave yourself out of it or to fight for Tang-Man''s future and turning the tide? The journey of yours,is unpredictable.' FROM games WHERE igdb_id = 203852 ON CONFLICT (game_id, language_code) DO NOTHING;
